	void queriesStillReachTheUpstreamEndpoint(String type, GraphAlgebraMode mode) throws Exception {
		try (var fixture = passthrough(type)) {
			var manager = manager(fixture.repository());
			var handler = new DefaultQueryRequestHandler(new DefaultRepositoryResolver(manager));
			Controller controller = (request, response) -> handler.handleQueryRequest(request, RequestMethod.GET,
					response);
			try {
				var request = new MockHttpServletRequest("GET", REPOSITORY_PATH);
				request.addParameter(Protocol.QUERY_PARAM_NAME, COUNT_QUERY);
				var options = QueryParseOptions.DEFAULT.withGraphAlgebraMode(mode);
				var response = exchange(manager, options, controller, request);
				assertThat(response.getStatus()).isEqualTo(200);
				assertThat(response.getContentAsString()).containsPattern("\"value\"\\s*:\\s*\"7\"");

				try (var connection = fixture.repository().getConnection()) {
					assertThatThrownBy(() -> connection.setQueryParseOptions(options))
							.isInstanceOf(UnsupportedOperationException.class);
				}

				// Strict syntax still requires support from the connection that executes the query.
				var strictRequest = new MockHttpServletRequest("GET", REPOSITORY_PATH);
				strictRequest.addParameter(Protocol.QUERY_PARAM_NAME, COUNT_QUERY);
				assertThatThrownBy(() -> exchange(manager, QueryParseOptions.STRICT.withGraphAlgebraMode(mode),
						controller, strictRequest)).isInstanceOf(UnsupportedOperationException.class);
			} finally {
				handler.shutdown();
			}
		}
	}

