	private static class RecordingRepository extends RepositoryWrapper {
		private final List<QueryParseOptions> observed = new ArrayList<>();
		private final MalformedQueryException prepareFailure;
		private final IllegalStateException restoreFailure;

		RecordingRepository(boolean failing) {
			this(failing, false);
		}

		RecordingRepository(boolean failing, boolean restoreFails) {
			super(new SailRepository(new MemoryStore()));
			prepareFailure = failing ? new MalformedQueryException("fixture preparation failure") : null;
			restoreFailure = restoreFails ? new IllegalStateException("fixture restore failure") : null;
		}

		@Override
		public RepositoryConnection getConnection() {
			var delegate = super.getConnection();
			delegate.setQueryParseOptions(PROVIDER_OPTIONS.withBlankNodeReferences(true));
			return new RepositoryConnectionWrapper(this, delegate) {
				@Override
				public void begin() {
					observed.add(getQueryParseOptions());
					super.begin();
				}

				@Override
				public void begin(TransactionSetting... settings) {
					observed.add(getQueryParseOptions());
					super.begin(settings);
				}

				@Override
				public void setNamespace(String prefix, String name) {
					observed.add(getQueryParseOptions());
					super.setNamespace(prefix, name);
				}

				@Override
				public Query prepareQuery(QueryLanguage language, String query, String baseURI) {
					observePreparation();
					return super.prepareQuery(language, query, baseURI);
				}

				@Override
				public Update prepareUpdate(QueryLanguage language, String update, String baseURI) {
					observePreparation();
					return super.prepareUpdate(language, update, baseURI);
				}

				@Override
				public void setQueryParseOptions(QueryParseOptions options) {
					boolean restoring = ENDPOINT_OPTIONS.equals(getQueryParseOptions())
							&& PROVIDER_OPTIONS.equals(options);
					super.setQueryParseOptions(options);
					if (restoring && restoreFailure != null) {
						throw restoreFailure;
					}
				}

				@Override
				public void close() {
					observed.add(getQueryParseOptions());
					super.close();
				}

				private void observePreparation() {
					observed.add(getQueryParseOptions());
					if (prepareFailure != null) {
						throw prepareFailure;
					}
				}
			};
		}
	}

