	private static PassthroughFixture passthrough(String type) {
		var transport = new FixtureTransport();
		if ("HTTP".equals(type)) {
			var repository = new HTTPRepository(UPSTREAM, "upstream");
			repository.setHttpClient(transport);
			return new PassthroughFixture(repository);
		}

		var repository = new SPARQLRepository(UPSTREAM + "/sparql", UPSTREAM + "/update");
		repository.setHttpClient(transport);
		if ("wrapped SPARQL".equals(type)) {
			return new PassthroughFixture(new RepositoryWrapper(repository) {
				@Override
				public RepositoryConnection getConnection() {
					return new RepositoryConnectionWrapper(this, super.getConnection());
				}
			});
		}
		return new PassthroughFixture(repository);
	}

	private record PassthroughFixture(Repository repository) implements AutoCloseable {
		@Override
		public void close() {
			repository.shutDown();
		}
	}

	private static MockHttpServletResponse exchange(RepositoryManager manager, QueryParseOptions options,
			Controller controller, MockHttpServletRequest request) throws Exception {
		var interceptor = new RepositoryInterceptor();
		interceptor.setQueryParseOptions(options);
		interceptor.setRepositoryManager(manager);
		request.setPathInfo(request.getRequestURI());
		request.addHeader("Accept", RESULTS_JSON);
		var response = new MockHttpServletResponse();
		interceptor.preHandle(request, response, controller);
		try {
			var result = controller.handleRequest(request, response);
			result.getView().render(result.getModel(), request, response);
			return response;
		} finally {
			interceptor.afterCompletion(request, response, controller, null);
		}
	}

	private static class FixtureTransport implements RDF4JHttpClient {
		private static final String REPO = "/repositories/upstream";

		@Override
		public HttpResponse execute(HttpRequest request) {
			return switch (request.getUri().getPath()) {
			case "/protocol" -> text(Protocol.VERSION);
			case REPO + "/size" -> text("7");
			case REPO + "/namespaces" -> response(200,
					"{\"head\":{\"vars\":[\"prefix\",\"namespace\"]},\"results\":{\"bindings\":[]}}",
					HttpHeader.of("Content-Type", RESULTS_JSON));
			case REPO, "/sparql" -> response(200,
					"{\"head\":{\"vars\":[\"count\"]},\"results\":{\"bindings\":[{\"count\":{\"type\":\"literal\",\"value\":\"7\"}}]}}",
					HttpHeader.of("Content-Type", RESULTS_JSON));
			case REPO + "/statements", "/update", REPO + "/transactions/fixture" -> response(204, "");
			case REPO + "/transactions" -> response(201, "",
					HttpHeader.of("Location", UPSTREAM + REPO + "/transactions/fixture"));
			default -> throw new AssertionError("Unexpected upstream request: " + request.getUri());
			};
		}

		private static HttpResponse text(String body) {
			return response(200, body, HttpHeader.of("Content-Type", "text/plain"));
		}

		private static HttpResponse response(int status, String body, HttpHeader... headers) {
			return new HttpResponse() {
				@Override
				public int getStatusCode() {
					return status;
				}

				@Override
				public String getReasonPhrase() {
					return "Fixture response";
				}

				@Override
				public List<HttpHeader> getHeaders() {
					return List.of(headers);
				}

				@Override
				public InputStream getBodyAsStream() {
					return new ByteArrayInputStream(body.getBytes(StandardCharsets.UTF_8));
				}

				@Override
				public void discard() {
				}

				@Override
				public void close() {
				}
			};
		}

		@Override
		public void close() {
		}
	}
